/* What the counters say, before anyone proposes a fix. */
typedef struct {
    double cpu_busy;      /* fraction of wall time on the CPU        */
    double disk_busy;     /* fraction of wall time the disk is busy  */
    long   major_faults;  /* page-ins from swap, per second          */
    long   runnable;      /* threads in the run queue                */
    long   blocked;       /* threads asleep on a lock                */
    long   retries;       /* failed trylock-and-release attempts     */
} snapshot;

const char *triage(snapshot s)
{
    if (s.disk_busy > 0.9 && s.cpu_busy < 0.2 && s.major_faults > 1000)
        return "thrashing: the working sets do not fit";
    if (s.cpu_busy < 0.05 && s.runnable == 0 && s.blocked > 0)
        return "deadlock: nobody is running and nobody will wake";
    if (s.cpu_busy > 0.95 && s.retries > 1000)
        return "livelock: running hard, completing nothing";
    return "no verdict - measure something else";
}

/* MLFQ, as rules rather than as five hundred lines. */
#define QUEUES 4

void mlfq_tick(job *j, int elapsed_ms)
{
    /* R1/R2: run the highest non-empty queue, round-robin within it. */
    j->used_ms += elapsed_ms;

    /* R4: demote on total allotment used, not on a single time slice,
       or a job that yields just before each slice expires keeps the
       top queue for ever. */
    if (j->used_ms >= allotment[j->queue] && j->queue < QUEUES - 1) {
        j->queue += 1;
        j->used_ms = 0;
    }
}

void mlfq_boost(job *all, int n)
{
    /* R5: periodically lift everything back to the top queue. This is
       the whole defence against starving a long job, and the only way
       a batch job that turns interactive is ever re-classified. */
    for (int i = 0; i < n; i++) {
        all[i].queue = 0;
        all[i].used_ms = 0;
    }
}

/* Clock: LRU's ordering, without LRU's bookkeeping. */
int clock_evict(frame *f, int n, int *hand)
{
    for (;;) {
        if (f[*hand].use == 0) {          /* untouched since the last sweep */
            int victim = *hand;
            *hand = (*hand + 1) % n;
            return victim;
        }
        f[*hand].use = 0;                 /* a second chance, and only one */
        *hand = (*hand + 1) % n;
    }
}

/* Reach is the quiet twin of this problem. The TLB is a cache of
   translations, so its capacity is measured in bytes of address space:
       reach = entries * page_size
   64 entries x 4 KiB = 256 KiB. A 2 MiB sweep misses on all 512 of its
   pages, every pass, however well the data cache behaves. */
size_t tlb_reach(size_t entries, size_t page_size)
{
    return entries * page_size;
}

/* A scheme submitted for review. Read the acquisition orders. */
struct table {
    pthread_rwlock_t resize;      /* held for writing while rehashing */
    bucket buckets[NBUCKETS];     /* each with its own mutex          */
};

int lookup(struct table *t, key k)
{
    pthread_rwlock_rdlock(&t->resize);
    bucket *b = bucket_for(t, k);
    pthread_mutex_lock(&b->m);            /* resize, then bucket */
    int v = bucket_find(b, k);
    pthread_mutex_unlock(&b->m);
    pthread_rwlock_unlock(&t->resize);
    return v;
}

int insert(struct table *t, key k, int v)
{
    bucket *b = bucket_for(t, k);
    pthread_mutex_lock(&b->m);            /* bucket, then resize */
    bucket_put(b, k, v);
    pthread_rwlock_rdlock(&t->resize);    /* to read the load factor */
    int full = t->count > NBUCKETS * 4;
    pthread_rwlock_unlock(&t->resize);
    pthread_mutex_unlock(&b->m);
    return full;
}
